const {DatabaseSync}=require('node:sqlite');const fs=require('node:fs');const crypto=require('node:crypto');
const path=require('node:path');const root=process.cwd();
function load(file){return JSON.parse(fs.readFileSync(path.join(root,'vendor',file),'utf8').replace(/^\uFEFF/,''))}
const italy=load('italy-2025.json'),official=load('official-programmes.json');
if(!Array.isArray(italy)||italy.length<1000||!Array.isArray(official)||!official.length)throw Error('Import rejected: incomplete dataset');
const sources={italy:{url:'https://ustat.mur.gov.it/opendata/',publishedPeriod:'2025/26',checkedAt:'2026-10-31',status:'historical'},official:{status:'source_checked'}};
const clean=v=>typeof v==='string'&&v.trim()&&!/^unknown$/i.test(v.trim())?v.trim():null;
const idFor=p=>'mur-'+crypto.createHash('sha256').update([p.title,p.university,p.level,p.city,p.academicYear].join('\0')).digest('hex').slice(0,20);
const field=(value,source)=>({value:clean(value),source:clean(value)?source:null});
const normalized=[];const ids=new Set();
for(const p of italy){if(!p.title||!p.university||!p.level||p.academicYear!=='2025/26')throw Error('Import rejected: malformed Italian record');const id=idFor(p);if(ids.has(id))continue;ids.add(id);const src=sources.italy;normalized.push({id,country:'Italy',type:'historical',source:src,fields:{title:field(p.title,src),university:field(p.university,src),country:field('Italy',src),degree:field(p.level,src),subject:field(p.subject,src),language:field(p.language,src),intake:field(null,src),tuition:field(null,src),requirements:field(null,src),scholarships:field(null,src),deadline:field(null,src),applicationStatus:field(null,src),city:field(p.city,src)}})}
for(const p of official){if(!p.id||!p.title||!p.source||!p.checked)throw Error('Import rejected: invalid official record');const src={url:p.source,checkedAt:p.checked,status:'source_checked'};const fields={};for(const k of ['title','university','country','degree','subject','language','intake','tuition','requirements','scholarships','deadline','applicationStatus'])fields[k]=field(p[k],src);normalized.push({id:p.id,country:p.country,type:'source_checked',source:src,fields})}
const deqarPath=path.join(root,'vendor','deqar-germany.json');
if(fs.existsSync(deqarPath)){const deqar=load('deqar-germany.json');if(!Array.isArray(deqar))throw Error('Invalid EQAR data');for(const p of deqar){if(!p.id||!p.title||!p.university||!p.source||!p.validUntil)throw Error('Invalid EQAR record');const src={url:p.source,checkedAt:p.checkedAt||'2026-10-31',status:'accreditation',validUntil:p.validUntil,attribution:'EQAR DEQAR, PDDL; accreditation evidence does not confirm current admissions'};const fields={};for(const k of ['title','university','degree'])fields[k]=field(p[k],src);fields.country=field('Germany',src);for(const k of ['subject','language','intake','tuition','requirements','scholarships','deadline','applicationStatus','city'])fields[k]=field(null,src);normalized.push({id:p.id,country:'Germany',type:'accreditation',source:src,fields})}}
const db=new DatabaseSync(path.join(root,'data','eunistud.sqlite'));db.exec('CREATE TABLE IF NOT EXISTS programme_catalog(id TEXT PRIMARY KEY,country TEXT NOT NULL,kind TEXT NOT NULL,content TEXT NOT NULL);CREATE VIRTUAL TABLE IF NOT EXISTS programme_search USING fts5(id UNINDEXED,title,institution,subject,city)');const insert=db.prepare('INSERT INTO programme_catalog VALUES(?,?,?,?)');const index=db.prepare('INSERT INTO programme_search VALUES(?,?,?,?,?)');db.exec('BEGIN IMMEDIATE');try{db.exec('CREATE TEMP TABLE prior_catalog AS SELECT id,content FROM programme_catalog;DELETE FROM programme_catalog;DELETE FROM programme_search');for(const p of normalized){insert.run(p.id,p.country,p.type,JSON.stringify(p));index.run(p.id,p.fields.title.value||'',p.fields.university.value||'',p.fields.subject.value||'',p.fields.city?.value||'')}if(db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='programme_embeddings'").get())db.exec('DELETE FROM programme_embeddings WHERE NOT EXISTS (SELECT 1 FROM programme_catalog c JOIN prior_catalog old ON old.id=c.id WHERE c.id=programme_embeddings.id AND c.content=old.content)');db.exec('COMMIT')}catch(e){db.exec('ROLLBACK');throw e}finally{db.close()}
console.log(JSON.stringify({italianRows:italy.length,imported:normalized.length,italianUnique:ids.size,official:official.length}));

